mapper.select:
SELECT P.CMPNY_CD AS cmpnyCd, P.PROGRM_FILE_NM AS progrmFileNm, P.PROGRM_NM_CODE AS progrmNmCode, M.MESSAGE_CN AS message_cn, P.PROGRM_URL AS progrmUrl, P.PROGRM_DC AS progrmDc, P.USE_FL AS useFl, P.CREATION_ID AS creationId, P.CREATION_DT AS creationDt, P.UPDATE_ID AS updateId, P.UPDATE_DT AS updateDt FROM CM_PROGRM P LEFT JOIN ( SELECT LANG_KEY, MESSAGE_CN FROM CM_MESSAGE_LANG WHERE CMPNY_CD = #{cmpnyCd} AND LANG_CODE = #{langCode} ) M ON M.LANG_KEY = P.PROGRM_NM_CODE WHERE P.CMPNY_CD = #{cmpnyCd}
AND ( M.MESSAGE_CN LIKE CONCAT('%', #{searchKeyword}, '%') OR P.PROGRM_URL LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY P.CREATION_DT DESC LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*)
FROM CM_PROGRM P
LEFT JOIN (
    SELECT LANG_KEY, MESSAGE_CN
    FROM CM_MESSAGE_LANG
    WHERE CMPNY_CD = #{cmpnyCd}
      AND LANG_CODE = #{langCode}
) M ON M.LANG_KEY = P.PROGRM_NM_CODE
WHERE P.CMPNY_CD = #{cmpnyCd}

         AND (
                M.MESSAGE_CN      LIKE CONCAT('%', #{searchKeyword}, '%')
                OR P.PROGRM_URL   LIKE CONCAT('%', #{searchKeyword}, '%')
            )

mapper.delete:
DELETE FROM CM_PROGRM
WHERE CMPNY_CD       = #{cmpnyCd}
  AND PROGRM_FILE_NM = #{progrmFileNm}
